/**
 * Cascade behind `ProjectService.archiveProject`; returns the row count. Every
 * issue of the project is stamped, so the whole project leaves the live
 * listings in one statement.
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

input.new_string:
/**
 * Cascade behind `ProjectService.archiveProject`. Only issues that are still
 * live are stamped; rows archived earlier keep their original `archivedAt`.
 * Returns how many issues this call newly archived.
 */
export async function archiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const rows = getDb()
    .update(issues)
    .set(archivePatch())
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .returning({ id: issues.id })
    .all();

  return rows.length;
}

