import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { eq } from "drizzle-orm";
import { subscribe } from "@/lib/event-bus";
import { getDb, issues } from "@/server/db";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("archive project leaves prior archives alone", () => {
  it("archives only live issues, keeps old archive dates, and recounts usage", async () => {
    const detach = registerUsageListeners();
    const tenant = await createTenant("archivemeter", "growth");
    const other = await projectRepo.insertProject({
      orgId: tenant.org.id,
      name: "Other",
      slug: "other",
      key: "OTH",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });

    const live = [];
    for (let i = 0; i < 9; i += 1) {
      live.push(
        await issueService.createIssue(
          tenant.actors.member,
          issueInput(tenant.org.id, tenant.project.id, { title: `Live ${i}` }),
        ),
      );
    }

    const prior = [];
    for (let i = 0; i < 3; i += 1) {
      const issue = await issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id, { title: `Old ${i}` }),
      );
      prior.push(await issueService.archiveIssue(tenant.actors.admin, tenant.org.id, issue.id));
    }

    const oldStamp = "2026-01-15T00:00:00.000Z";
    for (const issue of prior) {
      getDb()
        .update(issues)
        .set({ archivedAt: oldStamp, updatedAt: oldStamp })
        .where(eq(issues.id, issue.id))
        .run();
    }

    const outsider = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, other.id, { title: "Stays live" }),
    );

    await usageRepo.recomputeUsage(tenant.org.id);
    const before = await usageRepo.getUsage(tenant.org.id);
    expect(before.issuesUsed).toBe(10);

    const seen: number[] = [];
    const off = subscribe("project.archived", (payload) => {
      seen.push(payload.issuesArchived);
    });

    try {
      await projectService.archiveProject(tenant.actors.admin, {
        orgId: tenant.org.id,
        projectId: tenant.project.id,
        archiveIssues: true,
      });
    } finally {
      off();
      detach();
    }

    expect(seen).toEqual([9]);

    for (const issue of prior) {
      const row = await issueRepo.findIssueById(tenant.org.id, issue.id);
      expect(row?.archivedAt).toBe(oldStamp);
      expect(row?.updatedAt).toBe(oldStamp);
    }

    for (const issue of live) {
      const row = await issueRepo.findIssueById(tenant.org.id, issue.id);
      expect(row?.archivedAt).not.toBeNull();
      expect(row?.archivedAt).not.toBe(oldStamp);
    }

    const outsiderRow = await issueRepo.findIssueById(tenant.org.id, outsider.id);
    expect(outsiderRow?.archivedAt).toBeNull();

    const usage = await usageRepo.getUsage(tenant.org.id);
    const recounted = await usageRepo.recomputeUsage(tenant.org.id);
    expect(usage.issuesUsed).toBe(recounted.issuesUsed);
    expect(usage.issuesUsed).toBe(1);
  });
});

